import assert from 'node:assert/strict';
import { createHash, randomBytes } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolveIdentity, verifyIdentityToken } from '@volter/identity';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const issuer = (process.env.VOLTER_ISSUER || 'https://id.volter.ai').replace(/\/+$/, '');
const receiptFile = 'identity-records.json';
const callback = 'http://127.0.0.1:4310/auth/callback';
const cookiesOf = (res) => res.headers.getSetCookie().map((c) => c.split(';')[0]).filter((c) => !c.endsWith('=')).join('; ');
const json = { 'content-type': 'application/json' };
const form = { 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' };
const metadata = async () => { const found = await resolveIdentity(issuer, { fresh: true }); if (!found.available) throw new Error(found.reason); return found.metadata; };
const api = async (token, method, path, body) => {
  const res = await fetch(`${issuer}${path}`, { method, headers: { authorization: `Bearer ${token}`, accept: 'application/json', ...(body === undefined ? {} : json) }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
  const answer = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`${method} ${path}: ${res.status} ${JSON.stringify(answer)}`);
  return answer;
};

if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  const meta = await metadata();
  assert.equal(meta.issuer, issuer);
  const person = await verifyIdentityToken(saved.idToken, { issuer, audience: saved.clientId });
  assert.equal(person.subject, saved.person);
  const info = await (await fetch(meta.userinfo_endpoint, { headers: { authorization: `Bearer ${saved.accessToken}`, accept: 'application/json' } })).json();
  assert.equal(info.sub, saved.person);
  assert.equal(info.email, 'priya@orbit-apps.example');
  const found = await api(saved.organizationsToken, 'GET', `/api/people?email=${encodeURIComponent('priya@orbit-apps.example')}`);
  assert.equal(found.id, saved.person);
  const org = await api(saved.organizationsToken, 'GET', `/api/organizations/${saved.organization}`);
  assert.equal(org.name, 'Orbit Apps');
  const orgs = await api(saved.organizationsToken, 'GET', `/api/people/${saved.person}/organizations`);
  assert.deepEqual(orgs.map((o) => o.id), [saved.organization]);
  const members = await api(saved.organizationsToken, 'GET', `/api/organizations/${saved.organization}/members`);
  assert.deepEqual(members.map((m) => m.userId), [saved.person]);
  console.log(JSON.stringify({ retained: true, person: person.subject, organization: org.id, role: orgs[0].role }));
} else {
  // The operator: a signed-in Volter session and the service's admin token register the console, as at id.volter.ai.
  const operator = await (await fetch(`${issuer}/_twin/users`, { method: 'POST', headers: json, body: JSON.stringify({ email: 'operator@volter.example', name: 'Volter Operator' }) })).json();
  const priya = await (await fetch(`${issuer}/_twin/users`, { method: 'POST', headers: json, body: JSON.stringify({ email: 'priya@orbit-apps.example', name: 'Priya Shah' }) })).json();
  assert.ok(operator.id && priya.id);
  const operatorLogin = await fetch(`${issuer}/login`, { method: 'POST', redirect: 'manual', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ email: 'operator@volter.example', authorize: '' }) });
  const { admin_token } = await (await fetch(`${issuer}/_twin/app-credentials`, { method: 'POST', headers: json, body: '{}' })).json();
  const admin = { ...json, cookie: cookiesOf(operatorLogin), authorization: `Bearer ${admin_token}` };
  const made = await fetch(`${issuer}/admin/clients`, { method: 'POST', headers: admin, body: JSON.stringify({
    client_name: 'Twin console', redirect_uris: [callback], token_endpoint_auth_method: 'client_secret_post', application_type: 'native',
    grant_types: ['authorization_code', 'refresh_token', 'client_credentials'], client_credentials_scopes: ['organizations'], skip_consent: true, scope: 'openid profile email',
  }) });
  const client = await made.json();
  assert.equal(made.status, 201, JSON.stringify(client));
  assert.ok(client.client_id && client.client_secret);
  const linked = await fetch(`${issuer}/admin/clients/${client.client_id}/resources`, { method: 'POST', headers: admin, body: JSON.stringify({ resource: `${issuer}/organizations` }) });
  assert.ok(linked.ok, `link: ${linked.status} ${await linked.clone().text()}`);

  // Priya signs in to the console: authorize with PKCE, the sign-in page, the code traded with the client secret.
  const meta = await metadata();
  assert.equal(meta.issuer, issuer);
  const state = randomBytes(16).toString('base64url');
  const verifier = randomBytes(48).toString('base64url');
  const target = new URL(meta.authorization_endpoint);
  target.search = new URLSearchParams({ client_id: client.client_id, redirect_uri: callback, response_type: 'code', scope: 'openid profile email', state, code_challenge: createHash('sha256').update(verifier).digest('base64url'), code_challenge_method: 'S256' }).toString();
  const toLogin = await fetch(target, { redirect: 'manual' });
  assert.equal(toLogin.status, 302);
  const loginPage = new URL(toLogin.headers.get('location'), issuer);
  assert.equal(loginPage.pathname, '/login');
  const signedIn = await fetch(`${issuer}/login`, { method: 'POST', redirect: 'manual', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ email: 'priya@orbit-apps.example', authorize: target.searchParams.toString() }) });
  assert.equal(signedIn.status, 303);
  const authorized = await fetch(new URL(signedIn.headers.get('location'), issuer), { redirect: 'manual', headers: { cookie: cookiesOf(signedIn) } });
  const back = new URL(authorized.headers.get('location'));
  assert.equal(`${back.origin}${back.pathname}`, callback);
  assert.equal(back.searchParams.get('state'), state);
  const code = back.searchParams.get('code');
  assert.ok(code);
  const tokens = await (await fetch(meta.token_endpoint, { method: 'POST', headers: form, body: new URLSearchParams({ grant_type: 'authorization_code', code, code_verifier: verifier, redirect_uri: callback, client_id: client.client_id, client_secret: client.client_secret }) })).json();
  assert.ok(tokens.id_token && tokens.access_token, JSON.stringify(tokens));
  const person = await verifyIdentityToken(tokens.id_token, { issuer, audience: client.client_id });
  assert.equal(person.subject, priya.id);
  const info = await (await fetch(meta.userinfo_endpoint, { headers: { authorization: `Bearer ${tokens.access_token}`, accept: 'application/json' } })).json();
  assert.equal(info.sub, priya.id);
  assert.equal(info.email, 'priya@orbit-apps.example');
  assert.equal(info.name, 'Priya Shah');

  // The console's own organizations token; Priya found by email and her organization created.
  const granted = await (await fetch(meta.token_endpoint, { method: 'POST', headers: form, body: new URLSearchParams({ grant_type: 'client_credentials', client_id: client.client_id, client_secret: client.client_secret, scope: 'organizations', resource: `${issuer}/organizations` }) })).json();
  assert.ok(granted.access_token, JSON.stringify(granted));
  const found = await api(granted.access_token, 'GET', `/api/people?email=${encodeURIComponent('priya@orbit-apps.example')}`);
  assert.equal(found.id, priya.id);
  const org = await api(granted.access_token, 'POST', '/api/organizations', { name: 'Orbit Apps', slug: 'orbit-apps', createdBy: priya.id });
  assert.equal(org.name, 'Orbit Apps');
  assert.equal(org.slug, 'orbit-apps');
  const orgs = await api(granted.access_token, 'GET', `/api/people/${priya.id}/organizations`);
  assert.deepEqual(orgs.map((o) => o.id), [org.id]);
  assert.equal(orgs[0].role, 'owner');
  writeFileSync(receiptFile, JSON.stringify({ clientId: client.client_id, person: priya.id, organization: org.id, idToken: tokens.id_token, accessToken: tokens.access_token, organizationsToken: granted.access_token }) + '\n');
  console.log(JSON.stringify({ signedIn: info.email, person: priya.id, organization: org.id, role: orgs[0].role }));
}
